  {
    id = "fishing.status", feature = "fishing", title = "settings.card.fishing.status", intro = "fishing.set.intro", addon = "fishing",
    text = {
      ["fishing.set.intro"] = { de = "Hilft beim Angeln mit einer Taste oder einem Doppelklick, einem lauteren Bissgeräusch und weniger Namen im Bild. Jede Funktion bleibt aus, bis du sie einschaltest. Im Kampf ändert sich nichts.", en = "Helps while you fish with one key or a double click, a louder bite sound and fewer names on screen. Every function is off until you switch it on. Nothing changes in combat." },
      ["fishing.set.recheck"] = { de = "Erneut prüfen", en = "Check again" },
      ["fishing.set.recheckHint"] = { de = "Liest die Lage noch einmal. Nach einem blockierten Aufruf darf die Hilfe es erneut versuchen.", en = "Reads the situation again. After a blocked call it lets the helper try once more." },
      ["settings.card.fishing.status"] = { de = "Status", en = "Status" },
    },
    controls = {
      { key = "fishing.set.recheck", kind = "action", id = "fishing-recheck", hint = "fishing.set.recheckHint" },
    },
  },
  {
    id = "fishing.cast", feature = "fishing", title = "settings.card.fishing.cast", intro = "fishing.set.neverAuto", addon = "fishing",
    text = {
      ["fishing.opt.doubleClick"] = { de = "Auswerfen und Einholen mit einem Doppelklick", en = "Cast and reel in with a double click" },
      ["fishing.opt.doubleClick.hint"] = { de = "Zwei schnelle Rechtsklicks auf die Spielwelt tun dasselbe wie die Taste, ohne Taste und ohne den Schwimmer anzuvisieren: Angel draußen holt ein, sonst wirft aus.", en = "Two quick right clicks on the game world do what the key does, without a key or aiming at the bobber: line out reels in, otherwise it throws." },
      ["fishing.opt.doubleClickMounted"] = { de = "Doppelklick auch beim Reiten", en = "Double click also while riding" },
      ["fishing.opt.doubleClickMounted.hint"] = { de = "Erlaubt den Doppelklick auf dem Reittier. Die Taste wirkt beim Reiten nie.", en = "Allows the double click on a mount. The key never works while you ride." },
      ["fishing.opt.doubleClickTime"] = { de = "Doppelklick-Tempo", en = "Double click speed" },
      ["fishing.opt.doubleClickTime.hint"] = { de = "Längste Zeit zwischen den zwei Klicks, 0,1 bis 0,8 Sekunden. Mit Neuwurf wirft ein Klick nach dem Einholen erst nach der Pause aus, mindestens 0,4 s.", en = "Longest time between the two clicks, 0.1 to 0.8 seconds. With throw again on, a click after reeling in throws only after the pause, at least 0.4 s." },
      ["fishing.opt.oneKey"] = { de = "Auswerfen und Einholen mit einer Taste", en = "Cast and reel in with one key" },
      ["fishing.opt.oneKey.hint"] = { de = "Eine Taste wirft aus und holt ein. Sie tut nichts, solange die Beute nicht genommen ist. Belege sie unter Optionen > Tastenbelegung > AddOns > Auswerfen und Einholen.", en = "One key throws and reels in. It does nothing until the loot is taken. Set it under Options > Key Bindings > AddOns > Cast and reel in." },
      ["fishing.opt.recast"] = { de = "Nach dem Einholen neu auswerfen", en = "Throw again after reeling in" },
      ["fishing.opt.recast.hint"] = { de = "Nach dem Einholen wirft nichts aus, bis Pause und Beute durch sind. Mit gehaltener Umschalt-, Strg- oder Alt-Taste beim Einholen wirft danach ein einzelner Klick oder Druck aus, 5 Sekunden lang.", en = "After reeling in nothing throws until the pause and the loot are done. With Shift, Ctrl or Alt held while reeling in, a single click or press then throws, for 5 seconds." },
      ["fishing.opt.recastInvert"] = { de = "Zusatztaste umkehren", en = "Reverse the modifier key" },
      ["fishing.opt.recastInvert.hint"] = { de = "Dreht die Zusatztaste um: Ein einfaches Einholen merkt den Wurf vor, mit gehaltener Umschalt-, Strg- oder Alt-Taste holt es nur ein. Braucht den Schalter darüber.", en = "Turns the modifier round: a plain reel in prepares the throw, with Shift, Ctrl or Alt held it only reels in. Needs the switch above." },
      ["fishing.opt.recastPause"] = { de = "Pause vor dem Neuwurf", en = "Pause before throwing again" },
      ["fishing.opt.recastPause.hint"] = { de = "Mindestzeit nach dem Einholen, bevor der nächste Druck auswirft. Der Wurf wartet außerdem, bis die Beute genommen ist. Wirkt nur bei eingeschaltetem Neuwurf.", en = "The least time after reeling in before the next press throws. The throw also waits until the loot is taken. Only used while throwing again is on." },
      ["fishing.set.neverAuto"] = { de = "Ein Wurf braucht immer einen echten Druck. Das Addon wirft nie von selbst aus.", en = "A throw always needs a real press. The add-on never throws by itself." },
      ["settings.card.fishing.cast"] = { de = "Auswerfen und Einholen", en = "Cast and reel in" },
    },
    controls = {
      { key = "fishing.opt.oneKey", kind = "toggle", id = "fishing-oneKey", hint = "fishing.opt.oneKey.hint" },
      { key = "fishing.opt.doubleClick", kind = "toggle", id = "fishing-doubleClick", hint = "fishing.opt.doubleClick.hint" },
      { key = "fishing.opt.doubleClickTime", kind = "slider", id = "fishing-doubleClickTime", hint = "fishing.opt.doubleClickTime.hint" },
      { key = "fishing.opt.doubleClickMounted", kind = "toggle", id = "fishing-doubleClickMounted", hint = "fishing.opt.doubleClickMounted.hint" },
      { key = "fishing.opt.recast", kind = "toggle", id = "fishing-recast", hint = "fishing.opt.recast.hint" },
      { key = "fishing.opt.recastInvert", kind = "toggle", id = "fishing-recastInvert", hint = "fishing.opt.recastInvert.hint" },
      { key = "fishing.opt.recastPause", kind = "slider", id = "fishing-recastPause", hint = "fishing.opt.recastPause.hint" },
    },
  },
  {
    id = "fishing.sound", feature = "fishing", title = "settings.card.fishing.sound", addon = "fishing",
    text = {
      ["fishing.opt.autoLoot"] = { de = "Fänge automatisch plündern", en = "Loot catches automatically" },
      ["fishing.opt.autoLoot.hint"] = { de = "Nimmt jeden Gegenstand eines Fangs, sobald sich das Beutefenster öffnet, was das Spiel auch eingestellt hat.", en = "Takes every item of a catch as soon as the loot window opens, whatever the game setting says." },
      ["fishing.opt.bobberMark"] = { de = "Eigenes Symbol am Schwimmer", en = "Own icon at the bobber" },
      ["fishing.opt.bobberMark.hint"] = { de = "Ersetzt das Spielsymbol über dem Schwimmer durch ein eigenes Symbol, das näher am Schwimmer sitzt. Solange die Angel draußen ist, ist das Spielsymbol aus und das neue hängt an der Namensplakette des Schwimmers. Versteckt das Spiel diese Plakette, erscheint kein Symbol. Braucht die Taste oder den Doppelklick.", en = "Replaces the game icon above the bobber with an icon of your own that sits closer to it. While the line is out the game icon is off and the new one hangs on the name plate of the bobber. If the game hides that plate, no icon is shown. Needs the key or the double click." },
      ["fishing.opt.effectVolume"] = { de = "Effektlautstärke beim Angeln", en = "Effects volume while fishing" },
      ["fishing.opt.effectVolume.hint"] = { de = "Die Lautstärke des Reglers Effekte im Spiel, solange die Angel draußen ist. Das Platschen bei einem Biss ist ein Effekt.", en = "The volume of the Effects slider of the game while the line is out. The splash of a bite is an effect." },
      ["fishing.opt.hideBobberIcon"] = { de = "Symbol über dem Schwimmer ausblenden", en = "Hide the icon over the bobber" },
      ["fishing.opt.hideBobberIcon.hint"] = { de = "Entfernt das Spielsymbol über dem Schwimmer. Braucht die Taste oder den Doppelklick.", en = "Removes the game icon above the bobber. Needs the key or the double click." },
      ["fishing.opt.hideNames"] = { de = "Namen und Namensplaketten ausblenden", en = "Hide names and name plates" },
      ["fishing.opt.hideNames.hint"] = { de = "Solange die Angel draußen ist, sind Namensplaketten und NPC-Namen aus, damit sie deine Klicks nicht stören. Namen feindlicher NPCs bleiben. Danach kommen deine eigenen Einstellungen zurück.", en = "While the line is out, name plates and NPC names are hidden so they do not block your clicks. Names of enemy NPCs stay. Your own settings come back afterwards." },
      ["fishing.opt.improveSound"] = { de = "Lauterer Angelton", en = "Louder fishing sound" },
      ["fishing.opt.improveSound.hint"] = { de = "Solange die Angel draußen ist, werden Musik, Umgebung und Begleitergeräusche leise und Effekte laut, damit du den Biss hörst. Danach kommen deine eigenen Toneinstellungen zurück.", en = "While the line is out, music, ambience and pet sounds go quiet and effects play loud, so you hear the bite. Your own sound settings come back afterwards." },
      ["fishing.opt.markOffset"] = { de = "Abstand des Symbols", en = "Icon distance" },
      ["fishing.opt.markOffset.hint"] = { de = "Wie weit unter dem Ankerpunkt des Schwimmers das eigene Symbol sitzt, in Pixeln (ein kleinerer Wert liegt weiter unten). Der Standardwert ist nur ein Startwert: Ziehe den Regler bei ausgeworfener Angel, bis das Symbol passend über dem Schwimmer sitzt. Wirkt nur mit dem eigenen Symbol.", en = "How far below the anchor point of the bobber the own icon sits, in pixels (a lower value is further down). The default is only a starting value, pull the slider while the line is out until the icon sits right over the bobber. Only used with the own icon." },
      ["fishing.opt.soundVolume"] = { de = "Lautstärke beim Angeln", en = "Volume while fishing" },
      ["fishing.opt.soundVolume.hint"] = { de = "Die Gesamtlautstärke, solange die Angel draußen ist.", en = "The master volume while the line is out." },
      ["settings.card.fishing.sound"] = { de = "Ton und Anzeige", en = "Sound and display" },
    },
    controls = {
      { key = "fishing.opt.improveSound", kind = "toggle", id = "fishing-improveSound", hint = "fishing.opt.improveSound.hint" },
      { key = "fishing.opt.soundVolume", kind = "slider", id = "fishing-soundVolume", hint = "fishing.opt.soundVolume.hint" },
      { key = "fishing.opt.effectVolume", kind = "slider", id = "fishing-effectVolume", hint = "fishing.opt.effectVolume.hint" },
      { key = "fishing.opt.hideNames", kind = "toggle", id = "fishing-hideNames", hint = "fishing.opt.hideNames.hint" },
      { key = "fishing.opt.hideBobberIcon", kind = "toggle", id = "fishing-hideBobberIcon", hint = "fishing.opt.hideBobberIcon.hint" },
      { key = "fishing.opt.bobberMark", kind = "toggle", id = "fishing-bobberMark", hint = "fishing.opt.bobberMark.hint" },
      { key = "fishing.opt.markOffset", kind = "slider", id = "fishing-markOffset", hint = "fishing.opt.markOffset.hint" },
      { key = "fishing.opt.autoLoot", kind = "toggle", id = "fishing-autoLoot", hint = "fishing.opt.autoLoot.hint" },
    },
  },
  {
    id = "fishing.journal", feature = "fishing", title = "settings.card.fishing.journal", addon = "fishing",
    text = {
      ["fishing.opt.recordCatches"] = { de = "Fänge im Journal aufzeichnen", en = "Record catches in the journal" },
      ["fishing.opt.recordCatches.hint"] = { de = "Merkt sich jeden Fisch, den du fängst, je Charakter und für den Account, und wo. Es wird nichts versendet. Schalte es aus, um die Aufzeichnung zu beenden.", en = "Remembers every fish you catch, by character and for the account, and where. Nothing is sent anywhere. Switch it off to stop recording." },
